  "stuSess.penaltyChoiceRefundDesc": "Untuk pengembalian dana (€{amount}), hubungi info@tutlio.lt. Jika dibayar dengan kartu, pengembalian dana mungkin tetap diproses otomatis melalui Stripe.",
