  "stuSess.refundContactNote": "Untuk pengembalian dana, silakan hubungi <a href=\"mailto:info@tutlio.lt\" class=\"text-amber-800 underline\">info@tutlio.lt</a>.",
  "stuSess.refundSuccessStripeNote": "<p class=\"text-emerald-900 text-sm mb-2\">Ada pertanyaan atau kendala? Hubungi <a href=\"mailto:info@tutlio.lt\" class=\"underline font-medium\">info@tutlio.lt</a>.</p><p class=\"font-semibold text-emerald-900\">Pengembalian dana Anda telah dimulai melalui Stripe.</p><p class=\"text-emerald-800 mt-1\">Dana ke kartu biasanya diterima dalam sekitar <strong>5–10 hari kerja</strong> (bergantung pada bank). Jika belum diterima dalam jangka waktu normal, kirim email ke <a href=\"mailto:info@tutlio.lt\" class=\"text-emerald-900 underline font-medium\">info@tutlio.lt</a>.</p>",
  "stuSess.refundSuccessManualTutor": "<p>Pembayaran sesi les ini tampaknya tidak melalui Stripe Tutlio (mis. transfer bank atau tunai). Pengembalian dana otomatis tidak tersedia di sini.</p><p class=\"mt-2\">Untuk mengatur pengembalian dana, hubungi tutor <strong>{tutor}</strong> — gunakan email atau kontak dari pemesanan Anda atau langsung dari tutor.</p>",
  "stuSess.refundSuccessManualOrg": "<p>Pembayaran sesi les ini tampaknya tidak melalui Stripe Tutlio (mis. transfer bank atau tunai). Pengembalian dana otomatis tidak tersedia di sini.</p><p class=\"mt-2\">Karena Anda belajar melalui organisasi, hubungi <strong>administrator organisasi</strong> (melalui tutor atau kontak resmi organisasi).</p>",
