  "landing.faq.whatIsQ": "Apa itu Tutlio?",
  "landing.faq.whatIsA": "Tutlio adalah platform pengelolaan bimbel yang membantu tutor privat dan sekolah bimbel mengelola jadwal, pembayaran, komunikasi dengan siswa, dan pemantauan sesi les dari satu tempat.",
  "landing.faq.whoForQ": "Untuk siapa Tutlio dirancang?",
  "landing.faq.whoForA": "Tutlio dirancang untuk tutor privat, guru musik, pengajar bahasa, tutor matematika, sekolah bimbel, dan pusat pendidikan dengan berbagai skala.",
  "landing.faq.waitlistQ": "Bagaimana cara kerja daftar tunggu siswa?",
  "landing.faq.waitlistA": "Saat siswa membatalkan sesi les, slot yang tersedia otomatis ditawarkan kepada siswa dalam daftar tunggu. Siswa pertama yang mengonfirmasi mendapat slot tersebut - sehingga tutor tidak kehilangan pendapatan akibat pembatalan.",
  "landing.faq.freeTrialQ": "Apakah tersedia uji coba gratis?",
  "landing.faq.freeTrialA": "Ya! Setiap akun baru otomatis mendapat 7 hari gratis - tanpa kode. Tidak ada biaya selama masa uji coba, dan Anda dapat membatalkan kapan saja.",
  "landing.faq.languagesQ": "Bahasa apa saja yang didukung Tutlio?",
  "landing.faq.languagesA": "Tutlio tersedia dalam {count} bahasa: {languages}.",
  "landing.faqTitle": "Pertanyaan umum",
  "landing.feature.digital-business-card": "Kartu nama digital",
  "landing.feature.digital-business-cardDesc": "Bagikan satu halaman profesional tempat siswa dapat mengenal Anda, melihat harga dan waktu tersedia terkini, serta langsung mengajukan sesi les.",
  "featuresIndex.newBadge": "Baru",
  "feature.digital-business-card.pageTitle": "Kartu nama digital yang mengubah minat menjadi permintaan les",
  "feature.digital-business-card.pageDesc": "Berikan satu tautan yang tertata kepada setiap calon siswa, berisi profil, sesi les, harga, ulasan, dan waktu tersedia terkini. Mereka langsung memilih sesi dan waktu - permintaan pun tidak lagi terlewat di percakapan panjang.",
  "feature.digital-business-card.detailsTitle": "Semua informasi yang dibutuhkan calon siswa untuk memilih Anda",
  "feature.digital-business-card.oneLink": "Satu tautan untuk seluruh bisnis bimbel Anda",
  "feature.digital-business-card.oneLinkDesc": "Ganti profil media sosial, daftar harga, dan pesan pemesanan yang tersebar dengan satu halaman yang dapat Anda bagikan di mana saja.",
  "feature.digital-business-card.liveAvailability": "Waktu tersedia yang selalu diperbarui",
  "feature.digital-business-card.liveAvailabilityDesc": "Slot tersedia diambil langsung dari kalender Tutlio Anda, sehingga klien hanya mengajukan waktu yang memang Anda sediakan untuk mengajar.",
  "feature.digital-business-card.instantEnquiries": "Permintaan les masuk saat Anda mengajar",
  "feature.digital-business-card.instantEnquiriesDesc": "Orang tua atau siswa memilih sesi les, format, dan waktu, lalu mengisi data diri. Anda menerima permintaan lengkap tanpa perlu berdiskusi tentang jadwal.",
  "feature.digital-business-card.professionalBrand": "Kesan pertama yang profesional",
  "feature.digital-business-card.professionalBrandDesc": "Tampilkan foto, pendekatan mengajar, mata pelajaran, harga, ulasan terverifikasi, dan warna merek Anda pada halaman yang nyaman digunakan di ponsel apa pun.",
  "feature.digital-business-card.faq.whatShowsQ": "Apa saja yang bisa ditampilkan di kartu nama digital saya?",
  "feature.digital-business-card.faq.whatShowsA": "Anda dapat menampilkan perkenalan, mata pelajaran, format les, harga publik, slot kalender tersedia, lokasi, bahasa, tautan media sosial, dan ulasan siswa terverifikasi.",
  "feature.digital-business-card.faq.howBookingWorksQ": "Apakah pemesanan klien langsung menjadi sesi les yang dikonfirmasi?",
  "feature.digital-business-card.faq.howBookingWorksA": "Klien memilih sesi les dan waktu tersedia, lalu mengirim permintaan pemesanan lengkap. Anda menerimanya di Tutlio dan dapat mengonfirmasi siswa baru sebelum sesi ditambahkan ke jadwal Anda.",
  "feature.digital-business-card.faq.whereShareQ": "Di mana sebaiknya saya membagikan halaman ini?",
  "feature.digital-business-card.faq.whereShareA": "Gunakan di Instagram, TikTok, grup Facebook, iklan, tanda tangan email, pesan, dan kode QR. Tautannya tetap sama dan informasinya selalu terkini meskipun harga atau kalender Anda berubah.",
  "feature.digital-business-card.demo.eyebrow": "Pratinjau interaktif untuk klien",
  "feature.digital-business-card.demo.title": "Coba alur pemesanan",
  "feature.digital-business-card.demo.desc": "Pilih sesi les dan waktu di bawah. Inilah alur sederhana yang dilalui klien baru melalui tautan yang Anda bagikan.",
  "feature.digital-business-card.demo.profile": "Tutor matematika · kelas 9–12",
  "feature.digital-business-card.demo.available": "Menerima siswa baru",
  "feature.digital-business-card.demo.pickLesson": "1. Pilih sesi les",
