  "orgTutorPolicy.title": "Aturan internal untuk tutor",
  "orgTutorPolicy.intro": "Harap baca aturan internal organisasi sebelum menggunakan platform.",
  "orgTutorPolicy.acceptBtn": "Saya mengerti",
  "orgTutorPolicy.viewBtn": "Lihat aturan internal",
  "orgTutorPolicy.s1Title": "1. Ketentuan umum",
  "orgTutorPolicy.s1Body": "Aturan ini mengatur penggunaan platform Tutlio (\"Platform\") oleh Anda sebagai guru atau tutor (\"Tutor\"). Anda diundang menggunakan Platform oleh lembaga pendidikan, sekolah, atau pusat bimbel yang Anda wakili (\"Organisasi\"). Pemeliharaan teknis dan dukungan Platform disediakan oleh MB Tutlio. Dengan menggunakan akun, Anda menyetujui Aturan ini dan Kebijakan Privasi.",
  "orgTutorPolicy.s2Title": "2. Pengelolaan akun dan jadwal",
  "orgTutorPolicy.s2Intro": "Platform dirancang agar Anda tidak perlu menghabiskan waktu untuk mengoordinasikan jadwal les dengan siswa.",
  "orgTutorPolicy.s2Link": "Tautan unik: Anda mendapat tautan pemesanan les pribadi (berdasarkan mata pelajaran yang Anda ajarkan) yang digunakan siswa untuk menjadwalkan sesi les.",
  "orgTutorPolicy.s2Calendar": "Sinkronisasi kalender: Waktu tersedia Anda bergantung langsung pada integrasi Google Calendar (sinkronisasi 2 arah). Anda bertanggung jawab secara pribadi untuk memastikan waktu luang di kalender akurat dan terkini. Platform tidak mengizinkan siswa memesan waktu yang ditandai sibuk di kalender Anda.",
  "orgTutorPolicy.s2Security": "Keamanan akun: Akun Anda bersifat pribadi. Anda wajib menjaga keamanan kredensial masuk dan tidak membagikannya kepada pihak ketiga.",
  "orgTutorPolicy.s3Title": "3. Pembatalan les dan daftar tunggu",
  "orgTutorPolicy.s3Intro": "Platform membantu mengoptimalkan jadwal dan menghindari slot kosong:",
  "orgTutorPolicy.s3Auto": "Jika siswa membatalkan sesi les, Platform otomatis mengirim notifikasi (SMS/email) kepada siswa lain dalam daftar tunggu Anda untuk menawarkan slot yang tersedia. Anda tidak perlu melakukan tindakan tambahan.",
  "orgTutorPolicy.s3Rules": "Aturan pembatalan les (batas waktu pembatalan dan konsekuensinya) ditetapkan oleh Organisasi Anda.",
  "orgTutorPolicy.s4Title": "4. Keuangan dan pembayaran",
  "orgTutorPolicy.s4Intro": "Anda tidak perlu mengurus pembuatan faktur atau penagihan pembayaran kepada orang tua:",
  "orgTutorPolicy.s4Advance": "Semua pembayaran siswa (atau orang tua) untuk sesi les Anda diterima di muka melalui Platform dan ditransfer langsung ke Organisasi Anda.",
  "orgTutorPolicy.s4Confirmed": "Anda hanya memberikan sesi les yang sudah dikonfirmasi dalam sistem (artinya biaya sesi tersebut sudah ditagihkan).",
  "orgTutorPolicy.s4Contact": "Untuk gaji, jadwal pencairan dana, dan urusan keuangan lainnya, hubungi administrator Organisasi Anda secara langsung. MB Tutlio tidak melakukan transaksi keuangan langsung dengan Tutor.",
  "orgTutorPolicy.s5Title": "5. Perlindungan data siswa (GDPR)",
  "orgTutorPolicy.s5Intro": "Sebagai Tutor, Anda memiliki akses ke data pribadi siswa, catatan internal, dan materi belajar. Anda berkomitmen untuk:",
  "orgTutorPolicy.s5Use": "Menggunakan data ini hanya untuk mengatur dan memberikan sesi les.",
  "orgTutorPolicy.s5NoCopy": "Tidak menyalin, mengekspor, atau menyebarkan informasi kontak siswa atau orang tua di luar Platform.",
  "orgTutorPolicy.s5Notes": "Menjaga catatan internal Organisasi (catatan perkembangan siswa) yang hanya dapat dilihat oleh Anda dan administrasi Organisasi, bukan oleh siswa atau orang tua.",
  "orgTutorPolicy.s5Termination": "Saat hubungan kerja Anda dengan Organisasi berakhir, akses Anda ke data ini akan segera dicabut.",
  "orgTutorPolicy.s6Title": "6. Operasional teknis dan batasan tanggung jawab",
  "orgTutorPolicy.s6Body": "Dilarang menggunakan Platform untuk tujuan melanggar hukum, menyebarkan tautan berbahaya dalam materi les, atau mengganggu sistem dengan cara lain. MB Tutlio memastikan operasional dan pemeliharaan teknis Platform, tetapi tidak bertanggung jawab atas gangguan akibat koneksi internet Anda, kerusakan perangkat, atau pengaturan Google Calendar yang keliru.",
  "orgTutorPolicy.s7Title": "7. Dukungan dan kontak",
  "orgTutorPolicy.s7Org": "Untuk pertanyaan tentang jadwal les, gaji, penugasan siswa, atau pengaturan kerja, hubungi administrator Organisasi Anda.",
  "orgTutorPolicy.s7Tech": "Untuk masalah teknis Platform (sinkronisasi kalender tidak berfungsi atau notifikasi tidak diterima), beri tahu administrator Organisasi Anda, yang akan menghubungi tim dukungan teknis Tutlio.",
  "register.orgPolicyConsent": "Dengan menggunakan platform kami, Anda menyetujui",
  "register.orgPolicyLink": "kebijakan internal",
