  "quiz.info.story.company.story": "“Sebelum Tutlio, perubahan jadwal les, komentar, dan jam kerja tutor tersebar di berbagai pesan. Sekarang seluruh tim menggunakan jadwal yang sama, dan kami tidak perlu mengejar pembaruan pada akhir bulan.”",
