  "quiz.offer.testimonial.solo.name3": "Ieva",
  "quiz.offer.testimonial.solo.role3": "Tutor kimia dan biologi",
  "quiz.offer.testimonial.solo.copy3": "“Halaman publik dan pemesanan dalam satu tautan membantu siswa baru memutuskan lebih cepat, sementara saya tidak perlu lagi mengirim informasi yang sama kepada setiap orang.”",
  "quiz.offer.testimonial.solo.name4": "Lukas",
  "quiz.offer.testimonial.solo.role4": "Tutor fisika",
  "quiz.offer.testimonial.solo.copy4": "“Saya bisa langsung melihat sesi les, perubahan, dan status pembayaran di kalender. Administrasi harian menjadi jauh lebih singkat dan jelas.”",
  "quiz.offer.testimonial.company.name1": "PRO KLASĖ",
  "quiz.offer.testimonial.company.role1": "Tim organisasi bimbel",
  "quiz.offer.testimonial.company.copy1": "“Perubahan jadwal les, komentar tutor, dan jam kerja dulu masuk melalui pesan terpisah. Sekarang tim administrasi dapat melihat gambaran lengkap dalam satu jadwal.”",
  "quiz.offer.testimonial.company.name2": "Pusat bimbel mandiri",
  "quiz.offer.testimonial.company.role2": "Pemilik · 8 tutor",
  "quiz.offer.testimonial.company.copy2": "“Dulu saya menghabiskan Jumat malam untuk membandingkan kalender dengan pesan tutor sebelum menyiapkan pembayaran honor. Dengan Tutlio, sebagian besar pemeriksaan itu sudah selesai.”",
  "quiz.offer.testimonial.company.name3": "Studio bimbel bahasa",
  "quiz.offer.testimonial.company.role3": "Kepala operasional · 14 tutor",
  "quiz.offer.testimonial.company.copy3": "“Saat sesi les dipindahkan, tim langsung melihat pembaruan yang sama. Pesan tindak lanjut berkurang dan orang tua mendapat jawaban yang jauh lebih jelas.”",
  "quiz.offer.testimonial.company.name4": "Akademi persiapan ujian",
  "quiz.offer.testimonial.company.role4": "Koordinator keuangan · 22 tutor",
  "quiz.offer.testimonial.company.copy4": "“Aturan honor tutor kami berbeda menurut jenis les, jadi akhir bulan dulu membutuhkan banyak pemeriksaan manual. Alur kerja Tutlio membuat proses itu jauh lebih tenang.”",
  "quiz.offer.testimonial.school.name1": "VšĮ “Laisvi vaikai”",
  "quiz.offer.testimonial.school.role1": "Tim administrasi sekolah",
  "quiz.offer.testimonial.school.copy1": "“Perbaikan yang paling terasa adalah dapat melihat status kontrak, tanda tangan, dan pembayaran tanpa bertanya kepada beberapa orang atau memeriksa berkas terpisah.”",
  "quiz.offer.testimonial.school.name2": "Sekolah komunitas mandiri",
  "quiz.offer.testimonial.school.role2": "Koordinator penerimaan · 86 siswa",
  "quiz.offer.testimonial.school.copy2": "“Musim pendaftaran dulu berarti melacak formulir, data orang tua, dan perjanjian bertanda tangan di folder terpisah. Sekarang tim kami dapat mengikuti proses setiap keluarga dari satu tempat.”",
  "quiz.offer.testimonial.school.name3": "Pusat belajar sepulang sekolah",
  "quiz.offer.testimonial.school.role3": "Administrator · 120 siswa",
  "quiz.offer.testimonial.school.copy3": "“Jadwal cicilan membuat tindak lanjut pembayaran jauh lebih tenang. Saya dapat melihat tagihan yang jatuh tempo sebelum menghubungi orang tua, tanpa menyusun ulang daftar secara manual.”",
  "quiz.offer.testimonial.school.name4": "Sekolah pendidikan seni",
  "quiz.offer.testimonial.school.role4": "Koordinator keuangan · 9 program",
  "quiz.offer.testimonial.school.copy4": "“Ekspor akuntansi kini berasal dari data yang sama dengan yang kami gunakan untuk perjanjian dan pembayaran, sehingga koreksi pada akhir bulan jauh berkurang.”",
