  "nav.compare": "Perbandingan",
  "landing.custom.badge": "Perbedaan besarnya",
  "landing.custom.title": "Perangkat lunak yang menyesuaikan cara Anda bekerja - bukan sebaliknya",
  "landing.custom.sub": "Setiap sekolah dan agensi bekerja dengan cara yang sedikit berbeda. Ketika alur standar tidak cocok, kami menyesuaikan Tutlio dengan proses Anda - biasanya dalam hitungan minggu, bukan kuartal. Beberapa hal yang sudah kami buat untuk klien:",
  "landing.custom.ex1Title": "Kontrak tahunan dengan tanda tangan elektronik",
  "landing.custom.ex1Desc": "Sebuah sekolah swasta ingin orang tua menandatangani kontrak tahunan secara elektronik, membayar dengan cicilan, dan melihat setiap pembayaran dalam ekspor yang siap dipakai bagian akuntansi. Kini seluruh siklusnya berjalan di dalam Tutlio.",
  "landing.custom.ex2Title": "Aturan bayaran dan komisi tutor",
  "landing.custom.ex2Desc": "Sebuah agensi membayar tiap tutor menurut mata pelajaran dan jenis sesi, ditambah komisi perusahaan. Kami memodelkan aturan mereka sehingga rincian bulanan tutor dan faktur terbit otomatis.",
  "landing.custom.ex3Title": "Penawaran sekali klik untuk orang tua",
  "landing.custom.ex3Desc": "Sebuah sekolah ingin menawarkan sesi les tambahan lewat email dan membiarkan orang tua menyetujuinya dengan sekali klik - tanpa akun, tanpa cetak. Kini persetujuan, penagihan, dan undangan sesi pertama berjalan sendiri.",
  "landing.custom.ex4Title": "Identitas Anda, di situs Anda",
  "landing.custom.ex4Desc": "Sebuah organisasi menginginkan logo dan warnanya sendiri, ditambah halaman masuk yang tertanam di situsnya agar siswa dan orang tua tidak merasa meninggalkan situs. Kini Tutlio berjalan dengan identitas mereka.",
  "landing.custom.note": "Tidak satu pun dari ini merupakan versi khusus. Setiap penyesuaian menjadi bagian dari produk yang sama yang sudah dipakai tim Anda, lengkap dengan semua pembaruan berikutnya.",
  "landing.custom.cta": "Ceritakan cara Anda bekerja",
  "landing.custom.soloTitle": "Ada yang kurang?",
  "landing.custom.soloNote": "Kami rutin membangun fitur untuk klien tertentu - dari satu aturan pembayaran sampai satu alur kerja penuh. Beri tahu kami apa yang akan menghemat waktu Anda.",
  "compare.hub.badge": "Perbandingan",
  "compare.hub.title": "Tutlio dibandingkan dengan program pengelolaan les lainnya",
  "compare.hub.subtitle": "Perbandingan yang jujur, poin demi poin, dengan alat yang paling sering dipertimbangkan tutor dan bimbingan belajar. Kalau pesaing lebih cocok untuk Anda, kami katakan.",
  "compare.hub.metaTitle": "Tutlio vs TutorBird, TutorCruncher, Teachworks, Oases | Tutlio",
  "compare.hub.metaDesc": "Tutlio dibandingkan dengan TutorBird, TutorCruncher, Teachworks, dan Oases Online: fitur, model harga, bahasa, dan siapa yang paling cocok memakai masing-masing alat.",
  "compare.hub.cardCta": "Baca perbandingannya",
